const r = await tools.exec_command({cmd:"python - <<'PY'
import pandas as pd, calendar
p='/app/dataset/';e=pd.read_csv(p+'employees.csv',dtype={'PESEL':str});x=pd.read_csv(p+'timesheet.csv',dtype={'employee_id':str});x=x.drop_duplicates([c for c in x if c!='id']).copy();x=x[x.employee_id.isin(e.PESEL)].copy()
def fixdate(s):
 y,m,d=map(int,s.split('-'));return pd.Timestamp(y,m,min(d,calendar.monthrange(y,m)[1]))
x['d']=x.date.map(fixdate)
def per(d):
 first=d.replace(day=1)+pd.Timedelta(days=(1-d.replace(day=1).weekday())%7)
 return (d.to_period('M') if d>=first else d.to_period('M')-1).strftime('%Y-%m')
x['period']=x.d.map(per);rates=e.set_index('PESEL').hourly_rate
x['salhours']=(x.salary_amount/x.employee_id.map(rates)).astype(int)
x=x.sort_values(['employee_id','d','id']);x['cum']=x.groupby(['employee_id','period']).hours_worked.cumsum();x['diff']=x.salhours-x['cum']
print('counts',x.period.value_counts().sort_index().to_dict(),'matches',sum(x['diff']==0),'/',len(x))
print(x[x['diff']!=0][['id','date','d','period','employee_id','hours_worked','salhours','cum','diff']].to_string(index=False))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:20000});
text(r.output);

